def compute(vars):
    old_price = vars["v1"]
    new_price = vars["v2"]

    if old_price == 0:
        return None

    change_ratio = (new_price - old_price) / old_price
    growth_rate_percent = change_ratio * 100

    return {
        "value": growth_rate_percent,
        "trace": {
            "old_price": old_price,
            "new_price": new_price,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
